package drone_lifecycle_governor.Drone_Lifecycle_Governor

import org.sireum._
import art._
import drone_lifecycle_governor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait FlightAuthorizationPolicy_Api {
  def id: Art.BridgeId
  def decisionSnapshot_Id : Art.PortId
  def flightAuthorization_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var flightAuthorization: Drone_Lifecycle_Governor.FlightAuthorization.Type = $

  def put_flightAuthorization(value : Drone_Lifecycle_Governor.FlightAuthorization.Type) : Unit = {
    Contract(
      Modifies(flightAuthorization),
      Ensures(
        flightAuthorization == value
      )
    )
    Spec {
      flightAuthorization = value
    }

    Art.putValue(flightAuthorization_Id, Drone_Lifecycle_Governor.FlightAuthorization_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class FlightAuthorizationPolicy_Initialization_Api (
  val id: Art.BridgeId,
  val decisionSnapshot_Id : Art.PortId,
  val flightAuthorization_Id : Art.PortId) extends FlightAuthorizationPolicy_Api

@datatype class FlightAuthorizationPolicy_Operational_Api (
  val id: Art.BridgeId,
  val decisionSnapshot_Id : Art.PortId,
  val flightAuthorization_Id : Art.PortId) extends FlightAuthorizationPolicy_Api {

  // Logika spec var representing port state for incoming data port
  @spec var decisionSnapshot: Drone_Lifecycle_Governor.DecisionSnapshot = $

  def get_decisionSnapshot() : Option[Drone_Lifecycle_Governor.DecisionSnapshot] = {
    Contract(
      Ensures(
        Res == Some(decisionSnapshot)
      )
    )
    val value : Option[Drone_Lifecycle_Governor.DecisionSnapshot] = Art.getValue(decisionSnapshot_Id) match {
      case Some(Drone_Lifecycle_Governor.DecisionSnapshot_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port decisionSnapshot.  Expecting 'Drone_Lifecycle_Governor.DecisionSnapshot_Payload' but received ${v}")
        None[Drone_Lifecycle_Governor.DecisionSnapshot]()
      case _ => None[Drone_Lifecycle_Governor.DecisionSnapshot]()
    }
    return value
  }
}
